#  ★제목: 시리즈 틀(229 districts·Age-standardized) 금지, 쌍점 금지, 발견형. 미국식 철자. 단독 저자 무인칭. Results 숫자만, Discussion 숫자 없음.
import os, json
from content_waist_intro_methods import INTRO, methods
HERE = os.path.dirname(os.path.abspath(__file__)); N = json.load(open(os.path.join(HERE, "numbers_waist.json")))
def th(x, d=0): return f"{x:,.{d}f}"
def tc(k, src="main"):
    e, lo, hi = (N[src][k] if isinstance(src, str) else src); return f"{e:.3f} ({lo:.3f}-{hi:.3f})"
def cs(k, src="main"):
    e, lo, hi = (N[src][k] if isinstance(src, str) else src); return f"RR {e:.3f}; 95% CrI {lo:.3f}-{hi:.3f}"
def pct(x): return f"{100 * x:.0f}%"
def rng(k, srcs): v = [N[s][k][0] for s in srcs if s in N and k in N[s]]; return f"{min(v):.3f}-{max(v):.3f}"
def has(src, k): return src in N and k in N[src]
R = N["rate"]; RF = N["rate_full"]; MV = N.get("mv", {}); HC = N["hc"]; GH, GC = N["gi_hot_sido"], N["gi_cold_sido"]
KHS = ("KH_typeI", "KH_typeII", "KH_typeIII", "KH_typeIV"); REGS = ("Capital", "Yeongnam", "Honam", "Chungcheong", "Gangwon_Jeju")
TITLE = "Waist circumference measured at Korean health screening maps a social gradient in abdominal obesity across districts"
assert ":" not in TITLE and "229" not in TITLE and "standardi" not in TITLE.lower()
KEYWORDS = "Abdominal obesity; Waist circumference; Mass screening; Socioeconomic factors; Small-area analysis; Spatio-temporal analysis; Republic of Korea"
RUNNING = "Measured abdominal obesity across Korean districts"
METHODS = methods(N, th)
TITLE = "Abdominal obesity measured at Korean health screening is lower in districts with more university-educated adults"
assert ":" not in TITLE and "229" not in TITLE and "standardi" not in TITLE.lower()
BW = N["bw"]; TE, BL, UP = "tertiary_educated_share", "basic_livelihood_rate", "ext__screening_uptake"
def bw(c, s): return tc(None, BW[f"{c}__{s}"])
RSR = has("RSR", "tertiary")
hot_cn = GH.get("Chungnam", 0); cold_se = GC.get("Busan", 0) + GC.get("Gyeongnam", 0) + GC.get("Daegu", 0) + GC.get("Ulsan", 0)
NULL7 = ["walking_rate", "restaurant", "instant_food", "cars", "high_risk_drinking", "smoking_rate", "stress"]
mvnull = max(MV[k][0] for k in NULL7)

ABSTRACT = [
("Background", "District obesity data in Korea are mostly self-reported, but national health screening measures waist circumference in every attendee."),
("Methods", f"This ecological panel study covered {N['n_districts']} districts from 2019 to 2024 ({N['cases_total_m']:.1f} million attendances with abdominal obesity, waist circumference at least 90 cm in men or 85 cm in women, among {N['exam_total_m']:.1f} million attendances). Expected counts were standardized for sex and 15 age groups. Bayesian spatio-temporal negative binomial models related counts to 10 district characteristics (food and mobility environment, behaviors and stress, socioeconomic position, screening uptake)."),
("Results", f"District standardized ratios ranged from {N['sir_p10']:.2f} to {N['sir_p90']:.2f} (10th-90th percentile) with hot spots mainly in Chungnam and cold spots in south-eastern cities. Abdominal obesity was lower where more adults had tertiary education ({cs('tertiary')} per 1 SD), a between-district association retained in all {MV['tertiary'][2]} covariate subsets, in space-time interaction and spatial confounding models, and in 2013-2017, but not with an independent district effect only. Basic livelihood security ({cs('basic_livelihood_rate')}) and screening uptake ({cs('screening_uptake')}) were associated in the principal model but not under all space-time interaction models, and the livelihood estimate reversed under restricted spatial regression. Food outlets, registered cars, walking, drinking, smoking, and stress showed no consistent association; positive residual spatial autocorrelation remained."),
("Conclusions", "Measured abdominal obesity among Korean screening attendees is modestly higher in districts with fewer university-educated adults, a gradient that remained after adjustment for food outlets, registered cars, and survey-reported behaviors. Population-level prevention priorities need further evidence."),
]

def results():
    return [
("Abdominal obesity across districts",
 f"In 2019-2024, {N['cases_total_m']:.2f} million of {N['exam_total_m']:.1f} million attendances were above the waist cut-off; the national share of attendances was {R['2019']:.1f}% in 2019 and {R['2024']:.1f}% in 2024, compared with {RF['2013']:.1f}% in 2013 and {RF['2017']:.1f}% in 2017 (Table 1; Fig. 1B). The 6-year standardized ratio ranged from {N['sir_p10']:.2f} to {N['sir_p90']:.2f} between the 10th and 90th percentiles (ratio {N['p90p10']:.2f}; full range {N['sir_min']:.2f}-{N['sir_max']:.2f}); the 10th and 90th percentiles of the crude district shares were {N['crude_p10_p90'][0]:.1f}% and {N['crude_p10_p90'][1]:.1f}%. District rankings were stable (Kendall's W {N['kendall_w']:.2f}; Spearman ρ {N['rho_2019_2024']:.2f} between 2019 and 2024, and {N['rho_aux_main']:.2f} between the 2013-2017 and 2019-2024 ratios), and Moran's I of the yearly log ratios ranged from {N['moran_min']:.2f} to {N['moran_max']:.2f}.",
 f"Of {N['gi_hot']} hot spots, {hot_cn} were in Chungnam, with others in Gyeonggi, Jeonnam, Jeju, Gangwon, and Jeonbuk; of {N['gi_cold']} cold spots, {cold_se} were in Busan, Gyeongnam, Daegu, and Ulsan, and the others in Seoul ({GC.get('Seoul', 0)}), Gwangju ({GC.get('Gwangju', 0)}), Gyeongbuk ({GC.get('Gyeongbuk', 0)}), and Gyeonggi ({GC.get('Gyeonggi', 0)}) (Fig. 1A). The median share with tertiary education was {HC['hot']['ter']:.1f}% in hot spots and {HC['cold']['ter']:.1f}% in cold spots, and the median population density was {HC['hot']['dens']:.0f} and {HC['cold']['dens']:.0f} per km² (Fig. 1C). The district ratio was correlated with the self-reported obesity rate from the Community Health Survey (Spearman ρ {N['rho_sir_ob']:.2f}) and with the metabolic syndrome ratio from the same screening (ρ {N['rho_mets'][0]:.2f}; {N['rho_mets'][1]} districts)."),
("District characteristics",
 f"With the fixed adjustments only, the WAIC was {th(N['waic_forced_pois'],1)} for the Poisson and {th(N['waic_forced'],1)} for the negative binomial likelihood; adding the 10 characteristics lowered it to {th(N['waic_main'],1)} (Table 2). Abdominal obesity was lower with a higher share of tertiary education ({cs('tertiary')}) and higher screening uptake ({cs('screening_uptake')}) and higher with more basic livelihood security recipients ({cs('basic_livelihood_rate')}). The CrIs of the other 7 characteristics included 1, including walking ({tc('walking_rate')}), general restaurants ({tc('restaurant')}), and perceived stress ({tc('stress')}). Adding self-reported obesity changed the education estimate to {tc('tertiary', 's1b')}. The district effect had a mixing parameter of {N['phi']:.2f}, and district residuals remained positively autocorrelated (Moran's I {N['resid_moran'][0]:.3f}, expected {N['resid_moran'][1]:.4f}; none of 999 permutations was as extreme, 2-sided P ≤ .002), as they did in all 7 specifications assessed (Supplementary Table S5). Refitting the principal model gave the same WAIC and estimates."),
("Robustness",
 f"Tertiary education, basic livelihood security, and screening uptake were credible in all covariate subsets containing them ({MV['tertiary'][2]}, {MV['basic_livelihood_rate'][2]}, and {MV['screening_uptake'][2]} subsets) with full sign agreement; none of the other 7 characteristics was credible in more than {pct(mvnull)} of subsets. With Knorr-Held types I-IV, the education RR ranged from {rng('tertiary', KHS)}, all CrIs excluding 1; the livelihood RR ranged from {rng('basic_livelihood_rate', KHS)}, with the CrI including 1 under type IV ({tc('basic_livelihood_rate', 'KH_typeIV')}); and the uptake RR ranged from {rng('screening_uptake', KHS)}, with CrIs including 1 under types III and IV (Fig. 2; Supplementary Table S3). With Spatial+, the RRs were {tc('tertiary', 'D1_spatial_plus')} for education, {tc('basic_livelihood_rate', 'D1_spatial_plus')} for livelihood, and {tc('screening_uptake', 'D1_spatial_plus')} for uptake" + f". With restricted spatial regression, which constrains the district effect to be orthogonal to the characteristics, the RRs were {tc('tertiary', 'RSR')}, {tc('basic_livelihood_rate', 'RSR')}, and {tc('screening_uptake', 'RSR')}, and walking ({tc('walking_rate', 'RSR')}), high-risk drinking, smoking, and stress also had CrIs excluding 1, as in the model without a district effect (Supplementary Table S3). With province-by-year effects, they were {tc('tertiary', 'C4_sido_year_iid')}, {tc('basic_livelihood_rate', 'C4_sido_year_iid')}, and {tc('screening_uptake', 'C4_sido_year_iid')}. With an independent district effect only, the education RR was {tc('tertiary', 'iid_only')}. Excluding 2020-2021 gave {tc('tertiary', 'excl_2020_2021')}, {tc('basic_livelihood_rate', 'excl_2020_2021')}, and {tc('screening_uptake', 'excl_2020_2021')}.",
 f"The between-district education estimate excluded 1 ({bw(TE, 'between')}), whereas the within-district estimate did not ({bw(TE, 'within')}); for livelihood security the within-district estimate excluded 1 ({bw(BL, 'within')}) and the between-district estimate did not ({bw(BL, 'between')}); for uptake both excluded 1 ({bw(UP, 'between')} and {bw(UP, 'within')}). In 2013-2017, the RRs were {tc('tertiary', 'aux')} for education, {tc('basic_livelihood_rate', 'aux')} for livelihood, and {tc('screening_uptake', 'aux')} for uptake. For 2013-2024 including 2018, they were {tc('tertiary', 'full')}, {tc('basic_livelihood_rate', 'full')}, and {tc('screening_uptake', 'full')}. By region, the education RR ranged from {min(N['reg'][f'tertiary_educated_share|{r}'][0] for r in REGS):.3f} to {max(N['reg'][f'tertiary_educated_share|{r}'][0] for r in REGS):.3f}, with CrIs including 1 in Yeongnam and in Gangwon and Jeju (Supplementary Table S4). For metabolic syndrome from the same screening, they were {tc('tertiary', 'H1_nco_METSC')}, {tc('basic_livelihood_rate', 'H1_nco_METSC')}, and {tc('screening_uptake', 'H1_nco_METSC')}. Of the negative-control exposures, the traffic culture index was credibly associated ({tc(None, N['nc']['traffic_culture_index'])}); hit-and-run accidents and fires were not (Supplementary Table S4)."),
]

DISCUSSION = [
"Abdominal obesity measured at screening was modestly more common than expected in districts of Chungnam and other non-metropolitan provinces and less common in south-eastern cities, with a district ranking that was stable within 2019-2024 and similar to that of 2013-2017. The clearest district correlate was education: districts with more university-educated adults had less abdominal obesity, a between-district association that held across covariate subsets, space-time interaction and spatial confounding models, and the earlier period, although its credible interval included 1 when only an independent district effect was used. Deprivation and screening uptake were associated in the principal model, but their credible intervals included 1 under some space-time interaction models and the livelihood estimate reversed under restricted spatial regression; no consistent association was found with food outlets, registered cars, walking, drinking, smoking, or stress.",
"### An educational gradient measured by a tape",
"In Korean surveys, abdominal obesity has been inversely related to education and income among women, whereas among men higher socioeconomic position has been associated with more abdominal obesity, and these patterns have persisted over 2 decades [@yoo2010general; @jang2021trends; @jeong2026nationwide]. The present results show a gradient in the same direction at the district level, across all Korean districts and years, using national screening measurements; because the analysis pooled men and women, it cannot show whether the district gradient differs by sex. The association persisted under approximate standardization for sex and age, but residual differences in age composition and in who attends screening cannot be excluded, and metabolic syndrome from the same screening shares both its attendees and the waist component. Area-level socioeconomic inequalities in obesity have been reported across settings, with the built environment examined as a possible modifier [@area2023inequalities], and district education may summarize long-run differences in diet, work, and health literacy that the survey variables did not capture.",
"### Food outlets, travel, and behaviors",
"In systematic reviews, associations between obesity and the food environment varied by outlet type and access measure [@food2024environment], and inverse associations with walkability came mostly from cross-sectional studies [@walkability2019adults]; the present district-level analysis found no consistent association for restaurants, instant food businesses, registered cars, or walking. In individuals, alcohol intake has been associated with weight gain [@traversy2015alcohol], heavier smoking with a larger waist for a given body mass index among European-ancestry smokers [@morris2015heavier], perceived stress with small increases in adiposity [@wardle2011stress], and stress-related cortisol with abdominal fat in middle-aged men [@rosmond1998stress]. District survey rates come from a different sample, and these results show only that the education association remained after adjustment for these indicators, not that they are unrelated to adiposity in individuals.",
"### Deprivation and screening reach",
"The share of basic livelihood security recipients was associated only within districts over time, and the recipient series required correction for implausible values in 2021-2023, so this association may partly reflect data revisions as well as changing deprivation. In the principal model, higher screening uptake was associated with less abdominal obesity both between and within districts, although not with district-specific trends or province-by-year effects, compatible with wider attendance bringing in people with less adiposity; because the outcome is conditional on attendance, part of any district difference may reflect who attends rather than who lives there.",
"### Strengths and limitations",
"The study used measured waist circumference for all screening attendees in every district, checked the published table against attendance counts and excluded a year in which it covered only a subset, standardized for sex and age, and reported all space-time interaction and spatial confounding models. It has limitations. First, it is ecological, and associations do not describe individuals [@morgenstern1995ecologic]. Second, the outcome describes attendees, who are not the whole population, and attendance differs between districts. Third, the examinee age structure of each district was approximated from resident population and national attendance rates. Fourth, no data were available to assess differences in waist measurement between screening institutions. Fifth, positive residual spatial autocorrelation remained, and the traffic culture index, a negative-control exposure, was credibly associated with the outcome, indicating that unmeasured district characteristics are likely to confound the estimates to some degree [@lipsitch2010negative]. Sixth, the analysis used a frozen, read-only copy of a district dataset whose source-level verification was ongoing, and car registrations for Sejong were imputed. Seventh, men and women were pooled, so sex differences in the district gradient could not be examined. Finally, the range between districts was narrow, and the associations per 1 SD were small.",
]
CONCLUSION = ["Abdominal obesity measured at Korean health screening is modestly higher in non-metropolitan districts and lower in south-eastern cities, and it is lower where more adults are university educated across most model specifications. This association remained after adjustment for food outlets, registered cars, and survey-reported behaviors. Because the data describe screening attendees rather than all residents, district education may inform further assessment of where measured abdominal obesity is concentrated, but population-level prevention priorities require additional evidence."]
